    /** A link to BlogPage, e.g. https://www.stord.com/blog/navigating-dwell-time-in-ecommerce-logistics. */
    public static PageElement getBlogLink(String name) {
        String href = "/blog/" + name;
        // Written encoded ("Mast%20&%20Harbour") or not ("Mast & Harbour"): sites do both.
        String xpath = "xpath=//a[@href=" + Headings.literal(href) + " or @href="
                + Headings.literal(UrlPaths.decoded(href))
                + " or (contains(@href, '//') and (substring-after(substring-after(@href, '//'), '/')="
                + Headings.literal(href.substring(1)) + " or substring-after(substring-after(@href, '//'), '/')="
                + Headings.literal(UrlPaths.decoded(href).substring(1)) + "))] >> visible=true";
        return PageElement.of("BLOG_LINK", "the link to the blog page \"" + name + "\"", page -> page.locator(xpath)
                .first());
    }

